
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_cf22d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_cf22d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.173804497964723e-01, -1.168728261853266e-01, -1.159438462947393e-01, -1.141420974332194e-01, -1.104755164265140e-01, -1.028515704349530e-01, -8.736334844517786e-02, -5.798500422456697e-02, -5.838414333996396e-03, 5.763730868207176e-02, 3.349365243124533e-02, -6.830169672486641e-02, -4.162617972144825e-02, -2.868146963608673e-02, 4.231339182307672e-03, 1.132750628642966e-02, -2.165449505760438e-02, -1.535423865052003e-02, -4.505752489966514e-03, -6.432028776948659e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


